    derive: (i, deep) => {
      const p = (deep && deep.params) || {};
      const growth = p.growth || 1, peak = p.peak || 1, tiny = p.tiny || 1;
      const sm = i.small / 100, lg = Math.min(i.large / 100, 1 - sm), md = 1 - sm - lg;
      const avg0 = sm * 0.5 + md * 32 + lg * 200, avgMB = avg0 / tiny, usage = i.usage / 100;
      const dataPB = i.capPB * usage * growth, objects = (dataPB * 1e9) / avgMB;
      const writes = objects / YEAR, rd = i.read / 100, reads = (writes * rd) / (1 - rd), lists = ((reads + writes) * i.list) / 100;
      return {
        k: peak, peak, growth, tiny, sm, md, lg, avg0, avgMB, usage, dataPB, objects, writes, reads, lists,
        metaTB: (objects * i.metaKB) / 1e9, inMB: writes * avgMB, outMB: reads * avgMB,
        nodes3: Math.ceil((dataPB * 1000 * 3) / (NODE_TB * usage)),
        Wday: writes * DAY, Rday: reads * DAY, inTBday: (writes * DAY * avgMB) / 1e6,
      };
    },

